/* ============================================================================
   Public set v3 (2026-09-24). Fifty-four questions across twenty-seven categories,
   chosen because every answer CHANGED within the last twelve months: a model
   trained earlier answers from stale memory, and one with web search can look it
   up. Each was researched and then re-verified against its primary source by a
   second agent that opened the source itself; two of the fifty-six researched
   were thrown out (one wrong answer, one about to be superseded).

   Known answers are seeded the same way as v2: the current value, the previous
   values (graded Outdated, not Hallucinated) and any different-form value.
   ============================================================================ */

SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET XACT_ABORT ON;
GO

USE [LLMQuorum];
GO

IF NOT EXISTS ( SELECT 1 FROM quorum.QuestionSet WHERE Name = 'Public set v3' )
GO

DECLARE @set INT = ( SELECT QuestionSetId FROM quorum.QuestionSet WHERE Name = 'Public set v3' );
